<?php
session_start();if(empty($_SESSION['user_id'])){header('Location:/pages/login.php');exit;}require_once __DIR__.'/../config/config.php';$userId=(int)$_SESSION['user_id'];$errors=[];$success='';
$stmt=$pdo->prepare('SELECT * FROM users WHERE user_id=?');$stmt->execute([$userId]);$user=$stmt->fetch(PDO::FETCH_ASSOC);
if(empty($_SESSION['line_disconnect_csrf']))$_SESSION['line_disconnect_csrf']=bin2hex(random_bytes(24));
if($_SERVER['REQUEST_METHOD']==='POST'){$display=trim($_POST['display_name']??'');$bio=trim($_POST['bio']??'');$image=$user['profile_image'];$notifyPreference=(string)($_POST['notify_preference']??'email');if(!in_array($notifyPreference,['email','line','both','none'],true))$notifyPreference='email';if(in_array($notifyPreference,['line','both'],true)&&empty($user['line_user_id']))$errors[]='กรุณาเชื่อมต่อบัญชี LINE ก่อนเลือกการแจ้งเตือนผ่าน LINE';if($display==='')$errors[]='กรุณากรอกชื่อ';
 if(!empty($_FILES['profile_image']['name'])&&$_FILES['profile_image']['error']===UPLOAD_ERR_OK){$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['profile_image']['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png'][$mime]??null;if(!$ext||$_FILES['profile_image']['size']>5*1024*1024)$errors[]='รูปต้องเป็น JPG หรือ PNG ไม่เกิน 5 MB';else{$dir=__DIR__.'/uploads/profiles';if(!is_dir($dir))mkdir($dir,0775,true);$name='profile_'.$userId.'_'.bin2hex(random_bytes(5)).'.'.$ext;move_uploaded_file($_FILES['profile_image']['tmp_name'],$dir.'/'.$name);$image='uploads/profiles/'.$name;}}
 $current=$_POST['current_password']??'';$new=$_POST['new_password']??'';$confirm=$_POST['confirm_password']??'';$newHash=$user['password_hash'];if($new!==''||$current!==''){if(!$user['password_hash']||!password_verify($current,$user['password_hash']))$errors[]='รหัสผ่านปัจจุบันไม่ถูกต้อง';elseif(strlen($new)<8)$errors[]='รหัสผ่านใหม่ต้องมีอย่างน้อย 8 ตัวอักษร';elseif($new!==$confirm)$errors[]='ยืนยันรหัสผ่านใหม่ไม่ตรงกัน';else$newHash=password_hash($new,PASSWORD_DEFAULT);}
 $lat=isset($_POST['latitude'])&&$_POST['latitude']!==''?(float)$_POST['latitude']:null;$lng=isset($_POST['longitude'])&&$_POST['longitude']!==''?(float)$_POST['longitude']:null;if(!$errors){$pdo->prepare('UPDATE users SET display_name=?,bio=?,profile_image=?,password_hash=?,notify_preference=?,latitude=?,longitude=? WHERE user_id=?')->execute([$display,$bio?:null,$image,$newHash,$notifyPreference,$lat,$lng,$userId]);$_SESSION['display_name']=$display;$_SESSION['avatar']=$image?'/pages/'.$image:'';header('Location:/pages/profile.php?updated=1');exit;}
}
function editProfileImage(?string $v):?string{if(!$v)return null;return preg_match('#^https?://#i',$v)?$v:'/pages/'.ltrim($v,'/');}
?>
<style>.notification-setting{margin:24px 0;padding:18px;border:1px solid #eadbd4;border-radius:12px;background:#fffaf7}.notification-setting h2{margin:0 0 6px;color:var(--secondary-color);font-size:20px}.notification-setting p{margin:0 0 13px;color:var(--text-muted);font-size:13px}.notification-setting select{width:100%;height:46px;padding:0 12px;border:1px solid #ccd3c5;border-radius:8px;background:#fff;font:inherit}.line-unlinked{margin-top:9px;color:#b36d65;font-size:12px}</style>
<script>function disconnectLine(){const form=document.createElement('form');form.method='post';form.action='/pages/line_disconnect.php';const token=document.createElement('input');token.type='hidden';token.name='csrf_token';token.value=<?=json_encode($_SESSION['line_disconnect_csrf'])?>;form.append(token);document.body.append(form);form.submit()}</script>
<!DOCTYPE html><html lang="th"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>แก้ไขโปรไฟล์ - วนวรรณ</title><link rel="stylesheet" href="../assets/css/styles.css"><style>*{box-sizing:border-box}.account{display:flex;max-width:1280px;margin:auto}.content{flex:1;padding:48px 70px 90px}.form-card{max-width:850px;margin:auto;border:1px solid var(--secondary-color);border-radius:20px;padding:38px 60px}.avatar{text-align:center}.avatar-preview{width:125px;height:125px;margin:auto;border-radius:50%;overflow:hidden;background:#f7dfe8;display:grid;place-items:center;font-size:45px;color:var(--primary-color)}.avatar-preview img{width:100%;height:100%;object-fit:cover}.avatar input{margin:14px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.field{margin:18px 0}.field label{display:block;font-weight:600;color:var(--text-muted);margin-bottom:7px}.field input,.field textarea{width:100%;border:1px solid #ccd3c5;border-radius:8px;padding:13px;font:inherit;background:#faf9f8}.field textarea{min-height:100px}.security{color:var(--secondary-color);margin-top:28px}.actions{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:25px}.btn{height:52px;border-radius:8px;display:grid;place-items:center;font:inherit;text-decoration:none}.save{border:0;background:var(--secondary-color);color:#fff}.cancel{border:1px solid var(--secondary-color);color:var(--secondary-color)}.error{background:#fde5e1;color:#9b443c;padding:14px;border-radius:9px}@media(max-width:800px){.account{display:block}.content{padding:30px 16px}.form-card{padding:28px 20px}.grid{grid-template-columns:1fr}}</style></head><body><?php require __DIR__.'/../components/header.php';?><div class="account"><?php $profile_active='profile';require __DIR__.'/../components/profile_sidebar.php';?><main class="content"><form class="form-card" method="post" enctype="multipart/form-data"><?php if($errors):?><div class="error"><?=implode('<br>',array_map('htmlspecialchars',$errors))?></div><?php endif;?><div class="avatar"><div class="avatar-preview" id="preview"><?php if($img=editProfileImage($user['profile_image'])):?><img src="<?=htmlspecialchars($img)?>" alt=""><?php else:?><?=htmlspecialchars(mb_substr($user['display_name']?:'U',0,1))?><?php endif;?></div><h2>รูปโปรไฟล์ของคุณ</h2><input type="file" name="profile_image" id="profileImage" accept="image/jpeg,image/png"></div><div class="grid"><div class="field"><label>ชื่อ-นามสกุล</label><input name="display_name" value="<?=htmlspecialchars($_POST['display_name']??$user['display_name']??'')?>" required></div><div class="field"><label>อีเมล</label><input value="<?=htmlspecialchars($user['email'])?>" disabled></div></div><div class="field"><label>คำแนะนำตัว</label><textarea name="bio"><?=htmlspecialchars($_POST['bio']??$user['bio']??'')?></textarea></div><h2 class="security">📍 ตำแหน่งสำหรับนัดรับ</h2><p style="color:var(--text-muted);font-size:13px;margin:0 0 15px">พิกัดนี้จะใช้คำนวณระยะทางในระบบแลกเปลี่ยนและนัดรับหนังสือมือสอง</p><div class="grid"><div class="field"><label>ละติจูด (Latitude)</label><input type="text" name="latitude" id="inputLat" value="<?=htmlspecialchars($user['latitude']??'')?>" readonly placeholder="กดปุ่มเพื่อดึงพิกัด"></div><div class="field"><label>ลองจิจูด (Longitude)</label><input type="text" name="longitude" id="inputLng" value="<?=htmlspecialchars($user['longitude']??'')?>" readonly placeholder="กดปุ่มเพื่อดึงพิกัด"></div></div><button type="button" class="btn" style="background:#f3f4f6;color:var(--text-dark);border:1px solid #ccd3c5;height:42px;margin-bottom:20px;padding:0 15px" onclick="getLocation()">ดึงตำแหน่งที่ตั้งปัจจุบันของฉัน</button><h2 class="security">♙ การรักษาความปลอดภัย</h2><div class="field"><label>รหัสผ่านปัจจุบัน</label><input type="password" name="current_password"></div><div class="grid"><div class="field"><label>รหัสผ่านใหม่</label><input type="password" name="new_password" minlength="8"></div><div class="field"><label>ยืนยันรหัสผ่านใหม่</label><input type="password" name="confirm_password"></div></div><div class="actions"><button class="btn save">▣ บันทึกการเปลี่ยนแปลง</button><a class="btn cancel" href="/pages/profile.php">ยกเลิก</a></div></form></main></div><?php require __DIR__.'/../components/footer.php';?><script>document.getElementById('profileImage').addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader;r.onload=()=>document.getElementById('preview').innerHTML=`<img src="${r.result}" alt="ตัวอย่าง">`;r.readAsDataURL(f);});function getLocation(){if(navigator.geolocation){navigator.geolocation.getCurrentPosition(position=>{document.getElementById('inputLat').value=position.coords.latitude;document.getElementById('inputLng').value=position.coords.longitude;alert('ดึงตำแหน่งที่ตั้งสำเร็จ!')},error=>{alert('ไม่สามารถดึงตำแหน่งได้ กรุณาอนุญาตให้เบราว์เซอร์เข้าถึงตำแหน่ง (Location)')})}else{alert('เบราว์เซอร์ของคุณไม่รองรับการดึงตำแหน่งที่ตั้ง')}}</script></body></html>
